import {stats,league,best,multiplier} from './engine.js';

export const MODEL='neutral-benchmark-v2';
export const tierFromPercent=p=>p>=95?'S':p>=85?'A':p>=75?'B':p>=65?'C':p>=50?'D':p>=35?'E':'F';
export const purify=iv=>iv.map(x=>Math.min(15,x+2));
export function descendants(db,p){const out=[],seen=new Set();function visit(q){if(!q||q.mega||seen.has(q.id))return;seen.add(q.id);out.push(q);for(const id of q.evolutions||[])visit(db.pokemon.find(x=>x.id===id))}visit(p);return out;}
export function candidates(db,p,iv,max,shadow,cpFloor=.9,currentLevel=1){const result=[];for(const q of descendants(db,p)){for(const state of shadow?['shadow','purified']:['normal']){const values=state==='purified'?purify(iv):iv;for(const cap of [1500,2500]){const s=league(db,q,values,cap,max);if(!s||s.level<Math.max(currentLevel,state==='purified'?25:1))continue;const maximum=stats(db,q,[15,15,15],max).cp;result.push({species:q.id,name:q.name,state,iv:values,cap,...s,lowCP:maximum<cap*cpFloor,maximumCP:maximum});}}}return result.sort((a,b)=>Number(a.lowCP)-Number(b.lowCP)||b.percentile-a.percentile||b.percent-a.percent||a.name.localeCompare(b.name));}
export function previews(rows,threshold=90){const bests=[1500,2500].map(cap=>rows.find(r=>r.cap===cap)).filter(Boolean),qualified=bests.filter(r=>r.percentile>=threshold);return qualified.length>=2?qualified:bests.length?[...bests].sort((a,b)=>Number(a.lowCP)-Number(b.lowCP)||b.percentile-a.percentile).slice(0,1):[];}

// Explicit local benchmark; Poke Genie's proprietary simulator is not available.
// Neutral type interactions, 180 s, boss hit every 2 s, 10 s relobby,
// energy from incoming damage, capped at 100, damage applied on move completion.
export function simulate(db,p,iv,level,shadow,fast,charged,scenario){const f=db.moves[fast],c=db.moves[charged];if(!f||!c||f.energy<=0||c.energy>=0||!p.fast.includes(fast)||!p.charged.includes(charged)||shadow&&p.mega)return null;const s=stats(db,p,iv,level);let energy=0,hp=s.h,time=0,nextHit=2,damage=0,deaths=0;const attack=s.a*(shadow?1.2:1),hit=Math.floor(.5*scenario.power*scenario.attack/s.d*(shadow?1.2:1))+1;
 while(time<180){const m=energy>=-c.energy?c:f;const end=time+m.seconds;if(end>180)break;let faint=false;while(nextHit<=end&&nextHit<=180){hp-=hit;energy=Math.min(100,energy+Math.floor(hit/2));if(hp<=0){time=nextHit+10;nextHit=Math.ceil(time/2)*2+2;hp=s.h;energy=0;deaths++;faint=true;break}nextHit+=2}if(faint)continue;if(m===c)energy=Math.max(0,energy+c.energy);else energy=Math.min(100,energy+f.energy);damage+=m.power>0?Math.floor(.5*m.power*attack/scenario.defense*(p.types.includes(m.type)?1.2:1))+1:0;time=end;}return {dps:damage/180,damage,deaths};}
const scenarios=[{defense:150,attack:180,power:35},{defense:200,attack:220,power:45},{defense:250,attack:260,power:55}];
const profileCache=new Map();
export function skillProfile(db,p){const key=(db.sha256?.join()||'')+'|'+p.id;if(profileCache.has(key))return profileCache.get(key);const rows=[];for(const fast of p.fast)for(const charged of p.charged){if(db.moves[fast]?.energy<=0)continue;if(['FRUSTRATION','RETURN'].includes(charged))continue;let sum=0;for(const level of [40,45,50])for(const scenario of scenarios)sum+=simulate(db,p,[15,15,15],level,false,fast,charged,scenario)?.dps||0;rows.push({fast,charged,dps:sum/9});}rows.sort((a,b)=>b.dps-a.dps);const top=rows[0]?.dps||0;for(const row of rows){row.percent=top?row.dps/top*100:0;row.tier=tierFromPercent(row.percent)}profileCache.set(key,rows);return rows;}
// For battle-stat bars, factor the move cycle's neutral potency independently
// of attack, then multiply by attack/defense/HP exactly as described.
export function movePotency(db,p,fast,charged){const f=db.moves[fast],c=db.moves[charged];if(!f||!c||f.energy<=0||c.energy>=0)return null;const n=Math.ceil(-c.energy/f.energy);return (n*f.power*(p.types.includes(f.type)?1.2:1)+c.power*(p.types.includes(c.type)?1.2:1))/(n*f.seconds+c.seconds);}
let maximaCache=null;
function maxima(db){const key=db.sha256?.join()||'';if(maximaCache?.key===key)return maximaCache;let output=0,tank=0,duel=0;for(const q of db.pokemon){const s=stats(db,q,[15,15,15],50);let potency=0;for(const f of q.fast)for(const c of q.charged)if(!['FRUSTRATION','RETURN'].includes(c))potency=Math.max(potency,movePotency(db,q,f,c)||0);for(const sh of q.mega||!q.shadowAllowed?[false]:[false,true]){const o=s.a*potency*(sh?1.2:1),t=s.h*s.d/(sh?1.2:1);output=Math.max(output,o);tank=Math.max(tank,t);duel=Math.max(duel,o*t)}}return maximaCache={key,output,tank,duel};}
export function battleStats(db,p,shadow,fast,charged){const potency=movePotency(db,p,fast,charged);if(!potency||shadow&&p.mega)return null;const s=stats(db,p,[15,15,15],50),output=s.a*potency*(shadow?1.2:1),tank=s.h*s.d/(shadow?1.2:1),duel=output*tank,m=maxima(db);return {level:50,iv:[15,15,15],output:output/m.output*100,tank:tank/m.tank*100,duel:duel/m.duel*100,raw:{output,tank,duel}};}
export function raidRating(db,p,iv,level,shadow,fast,charged){const rows=skillProfile(db,p),chosen=rows.find(x=>x.fast===fast&&x.charged===charged);let current=null;if(level&&fast&&charged){const values=scenarios.map(s=>simulate(db,p,iv,level,shadow,fast,charged,s));if(values.every(Boolean))current={dps:values.reduce((a,b)=>a+b.dps,0)/values.length,deaths:values.reduce((a,b)=>a+b.deaths,0)/values.length};}return {model:MODEL,moves:rows,chosen:chosen||null,current,battle:fast&&charged?battleStats(db,p,shadow,fast,charged):null};}
export function rankingTable(db,p,cap,max){const rows=[];for(let a=0;a<16;a++)for(let d=0;d<16;d++)for(let h=0;h<16;h++){const s=best(db,p,[a,d,h],cap,max);if(s)rows.push({iv:[a,d,h],...s})}rows.sort((a,b)=>b.product-a.product);let rank=1;return rows.map((r,i)=>{if(i&&Math.abs(rows[i-1].product-r.product)>1e-7)rank=i+1;return {...r,rank,percentile:(4096-rank)/4095*100,percent:r.product/rows[0].product*100}});}

